TITLE = "Week 15: Allergy, autoimmunity and vaccines"
LEDE = "When the immune system overreacts to harmless things (allergy) or attacks the self (autoimmunity), how allergists test for it, and how vaccines are made, monitored and discussed with hesitant families."
LECTURES = ["Approach to allergy (Kuprowski)", "Understanding allergy testing (Kuprowski)", "Approach to allergy through different lenses (Kuprowski)",
            "Mechanisms of autoimmunity and clinical autoimmunity (Barra)", "Approach to autoimmune disease (Kuprowski)",
            "Vaccine hesitancy case application (Barton)", "Vaccine side effects and AEFI (Mohammadi)"]

