        cols(("Food", UL("About 5 to 7 steps, 15 to 30 min apart", "Aim for an age-appropriate serving: 8 to 10 g dry food or 100 mL wet food")), ("Drug", UL("Single step: full dose", "Two step: 10%, wait, then 90%"))),
